import jwt from 'jsonwebtoken'

export type SessionClaims = { sub: string; name: string; roles: string[]; exp: number }

// Reads the claims out of the access token so the UI can show the user's name and hide admin links.
// The client never verifies the signature — the API does that on every request.
export function readClaims(token: string): SessionClaims | null {
  const decoded = jwt.decode(token)
  return decoded && typeof decoded === 'object' ? (decoded as SessionClaims) : null
}

export function isExpired(claims: SessionClaims, now = Date.now()): boolean {
  return claims.exp * 1000 <= now
}

